import { Link, useRouterState } from "@tanstack/react-router";
import { useEffect, useRef, useState } from "react";

export function Brand() {
  // Generated by `pnpm brand:assets`.
  return (
    <img
      className="brand"
      src="/brand/yarrow-logo-on-dark.svg"
      alt="Yarrow"
      width={107}
      height={24}
    />
  );
}

const links = [
  { to: "/leaderboard", label: "Leaderboard" },
  { to: "/shipped", label: "Shipped" },
] as const;

type HeaderViewer = {
  name: string | null;
  githubLogin: string | null;
  avatarUrl: string | null;
} | null;

export function SiteHeader({ viewer }: { viewer: HeaderViewer }) {
  const path = useRouterState({ select: (state) => state.location.pathname });
  const [open, setOpen] = useState(false);
  const menu = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const close = (event: MouseEvent) => {
      if (!menu.current?.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", close);
    return () => document.removeEventListener("mousedown", close);
  }, [open]);
  const label = viewer?.githubLogin ?? viewer?.name ?? "Account";
  return (
    <header className="site-header">
      <div className="container header-inner">
        <Link to="/" aria-label="Yarrow home">
          <Brand />
        </Link>
        <nav aria-label="Primary" className="main-nav">
          {links.map((link) => (
            <Link
              key={link.to}
              to={link.to}
              aria-current={path.startsWith(link.to) ? "page" : undefined}
            >
              {link.label}
            </Link>
          ))}
        </nav>
        <div className="header-actions" ref={menu}>
          {viewer ? (
            <>
              <button
                className="avatar-button"
                aria-label={`${label} menu`}
                aria-haspopup="menu"
                aria-expanded={open}
                onClick={() => setOpen(!open)}
              >
                {viewer.avatarUrl ? (
                  <img src={viewer.avatarUrl} alt="" />
                ) : (
                  label.charAt(0).toUpperCase()
                )}
              </button>
              {open && (
                <div className="account-menu" role="menu">
                  <Link
                    to="/dashboard"
                    hash="projects"
                    role="menuitem"
                    onClick={() => setOpen(false)}
                  >
                    My projects
                  </Link>
                  <Link
                    to="/dashboard"
                    hash="sponsoring"
                    role="menuitem"
                    onClick={() => setOpen(false)}
                  >
                    My sponsoring
                  </Link>
                  <a href="/auth/sign-out" role="menuitem" className="muted">
                    Sign out
                  </a>
                </div>
              )}
            </>
          ) : (
            <Link to="/sign-in" className="sign-in">
              Sign in
            </Link>
          )}
        </div>
      </div>
    </header>
  );
}
